import{_ as a,c as e,a5 as r,o as i}from"./chunks/framework.mFcBg5UA.js";const l="/my-blog/img/how_about_tarui.png",p=JSON.parse('{"title":"Tauri 怎么样","titleTemplate":"Tauri应用开发实践指南","description":"","frontmatter":{"outline":"deep","title":"Tauri 怎么样","titleTemplate":"Tauri应用开发实践指南","head":[["link",{"rel":"canonical","href":"https://luffy-d-lufei.github.io/my-blog/summary/tauri/how_about_tauri.html"}]]},"headers":[],"relativePath":"summary/tauri/how_about_tauri.md","filePath":"summary/tauri/how_about_tauri.md","lastUpdated":1724763287000}'),d={name:"summary/tauri/how_about_tauri.md"};function u(o,t,h,n,c,s){return i(),e("div",null,t[0]||(t[0]=[r('<h1 id="tauri-怎么样" tabindex="-1">Tauri 怎么样 <a class="header-anchor" href="#tauri-怎么样" aria-label="Permalink to &quot;Tauri 怎么样&quot;">​</a></h1><h2 id="tarui是什么" tabindex="-1">Tarui是什么 <a class="header-anchor" href="#tarui是什么" aria-label="Permalink to &quot;Tarui是什么&quot;">​</a></h2><p>Tauri 是一个用于构建针对所有主要桌面和移动平台的小型、高速二进制文件的框架。开发人员可以集成任何能编译为 HTML、JavaScript 和 CSS 的前端框架来构建用户体验,同时在需要时利用诸如 Rust、Swift 和 Kotlin 等语言进行后端逻辑开发。 官网： <a href="https://tauri.app/zh-cn/" target="_blank" rel="noreferrer">https://tauri.app</a></p><h2 id="tarui架构" tabindex="-1">Tarui架构 <a class="header-anchor" href="#tarui架构" aria-label="Permalink to &quot;Tarui架构&quot;">​</a></h2><p>Tauri 的整体架构，自顶向下可以分为三层：</p><ol><li>tauri-app：整合所有模块，读取项目配置，完成最终 APP 产物的打包；主要负责初始化 Web APP 与底层系统 API 的通信环境，注入全局 API，管理应用更新等。</li><li><a href="https://github.com/tauri-apps/wry" target="_blank" rel="noreferrer">WRY</a>：一个跨平台 Webview 渲染库，会根据各平台选择特定的浏览器引擎启动 Webview，抹平平台差异，暴露统一的上层 API。</li><li><a href="https://github.com/tauri-apps/tao" target="_blank" rel="noreferrer">TAO</a>：跨平台应用窗口管理器，主要用于构建各平台下的应用主窗口。</li></ol><p><img src="'+l+'" alt="image.png"> Tauri 除了完全使用 rust 开发以外，与 electron 最大的不同之处就在于，没有使用直接为每个应用单独集成一个 chromium 环境，而是直接使用操作系统内置的浏览器引擎执行 Web APP，也就是这里提到的：WRY。</p><table tabindex="0"><thead><tr><th>操作系统</th><th>浏览器引擎</th><th>说明</th></tr></thead><tbody><tr><td>macOS</td><td>webkit</td><td>系统内置，理论上表现最好的平台</td></tr><tr><td>Linux</td><td>WebKitGTK</td><td>gtk + webkit</td></tr><tr><td>Windows</td><td>WebView2</td><td>从win7起，内置edge chromium中的浏览器引擎</td></tr></tbody></table><p>参考：<a href="https://tauri.app/v1/references/architecture/" target="_blank" rel="noreferrer">https://tauri.app/v1/references/architecture/</a></p><h2 id="tauri可以做什么" tabindex="-1">Tauri可以做什么 <a class="header-anchor" href="#tauri可以做什么" aria-label="Permalink to &quot;Tauri可以做什么&quot;">​</a></h2><p>基于其优秀的性能和可靠的安全性,Tauri可以用于构建各种类型的桌面应用程序,包括但不限于:</p><ul><li>本地化工具:如IDE、代码编辑器、文件管理器等。</li><li>多媒体应用:如音乐播放器、视频播放器、流媒体客户端等。</li><li>游戏和娱乐应用:如小游戏、电子书阅读器等。</li><li>办公和生产力工具:如文字处理器、电子表格、任务管理器等。</li><li>系统工具和实用程序:如系统监视器、备份工具、系统清理工具等。</li></ul><h2 id="跨端桌面端框架对比" tabindex="-1">跨端桌面端框架对比 <a class="header-anchor" href="#跨端桌面端框架对比" aria-label="Permalink to &quot;跨端桌面端框架对比&quot;">​</a></h2><p>这里我们只比较跨端桌面端框架，因为原生的桌面端开发和这些框架在一个纬度上没有什么可比性。差不多有Tauri，Electron，Flutter，React Native，QT这些框架， 我们将从性能，用户界面，原生集成，社区生态，成功案例，开发经验，开发挑战这些方面去比较。</p><h3 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h3><ul><li>Tauri:作为一个基于WebView的轻量级框架,Tauri的资源占用极小,能够构建快速、高响应的桌面应用程序。它的性能表现远好于基于Chromium的Electron。</li><li>Electron:因使用了完整的Chromium浏览器渲染进程,Electron应用通常占用较高的内存和CPU资源,在较低配置的设备上可能会表现不佳。</li><li>Flutter:Flutter的性能值得称赞,它使用了Ahead-of-Time(AOT)和Just-In-Time(JIT)编译技术,能够提供流畅的60fps的UI渲染和快速的启动时间。</li><li>React Native:React Native桌面应用的性能通常可以达到中等水平,但在保证跨平台一致性的同时,可能需要一些性能优化工作。</li><li>Qt:作为一个成熟的本地框架,Qt能够提供接近原生应用的卓越性能表现,非常适合开发资源密集型的应用程序。</li></ul><h3 id="用户界面" tabindex="-1">用户界面 <a class="header-anchor" href="#用户界面" aria-label="Permalink to &quot;用户界面&quot;">​</a></h3><ul><li>Tauri:前端使用Web技术开发,UI体验类似现代Web应用,后端可渲染原生UI控件。</li><li>Electron:基于Chromium浏览器内核渲染,Electron应用的UI通常不同于原生应用,但提供了强大的Web技术支持。</li><li>Flutter:Flutter拥有自身的modern、流畹的设计语言和丰富的widget库,为跨平台提供了一致的视觉体验。</li><li>React Native:使用了与React相似的组件架构,支持平滑的动画和触摸手势,但需要额外的工作来实现原生体验。</li><li>Qt:作为原生框架,Qt能带来接近本地的UI体验,提供大量的UI控件和动画支持。</li></ul><h3 id="原生集成" tabindex="-1">原生集成 <a class="header-anchor" href="#原生集成" aria-label="Permalink to &quot;原生集成&quot;">​</a></h3><ul><li>Tauri:利用Rust语言天生的系统编程特性,Tauri后端可以直接访问操作系统API和硬件资源。</li><li>Electron:通过Node.js的原生模块和一些第三方库,可以实现对系统API和硬件的集成。</li><li>Flutter:Flutter有自身的平台通道接口,可以调用原生代码并实现硬件和系统功能集成。</li><li>React Native:通过内置的桥接机制,可以调用底层平台的原生API和SDK。</li><li>Qt:作为本地框架,Qt可以完全利用平台的原生功能和硬件支持。</li></ul><h3 id="社区生态" tabindex="-1">社区生态 <a class="header-anchor" href="#社区生态" aria-label="Permalink to &quot;社区生态&quot;">​</a></h3><ul><li>Tauri:作为新兴框架,Tauri的社区较小但非常活跃,正在快速发展壮大。</li><li>Electron:基于Node.js和Chromium,拥有活跃的开发者社区和大量的第三方库支持。</li><li>React Native:Facebook主导的项目,拥有庞大的社区和大量教程文档支持。</li><li>Flutter:Google全力推动的开源项目,社区生态日益繁荣,拥有丰富的插件和学习资源。</li><li>Qt:作为成熟的框架,Qt拥有完备的文档和培训资源,拥有可观的应用案例。</li></ul><h3 id="成功案例" tabindex="-1">成功案例 <a class="header-anchor" href="#成功案例" aria-label="Permalink to &quot;成功案例&quot;">​</a></h3><ul><li>Tauri:虽然较新,但已有多个知名项目基于Tauri,如Blink Shell、Lyo IM等。可参考：<a href="https://github.com/tauri-apps/awesome-tauri" target="_blank" rel="noreferrer">https://github.com/tauri-apps/awesome-tauri</a></li><li>Electron:VSCode、Slack、WhatsApp等知名桌面应用均基于Electron构建。可参考：<a href="https://www.electronjs.org/apps" target="_blank" rel="noreferrer">https://www.electronjs.org/apps</a></li><li>React Native:Facebook、Instagram、Ubereats等大型应用都采用了React Native。</li><li>Flutter:Google自家多款应用使用Flutter开发,如Google Assistant、Google Stadia等。</li><li>Qt:广泛应用于多媒体、工业控制、电子书等多个领域。</li></ul><h3 id="开发经验" tabindex="-1">开发经验 <a class="header-anchor" href="#开发经验" aria-label="Permalink to &quot;开发经验&quot;">​</a></h3><ul><li>Tauri:前端使用Web框架,后端使用Rust语言,两者通过IPC通信。</li><li>Electron:基于Web技术,前端使用HTML/JS/CSS,后端使用Node.js。</li><li>React Native:类React编程范式,JSX语法,可重用React Web代码。</li><li>Flutter:使用Dart语言开发,采用声明式编程风格编写UI。</li><li>Qt:使用C++或QML(类JavaScript)语言,提供完整的IDE和工具链支持。</li></ul><h3 id="开发挑战" tabindex="-1">开发挑战 <a class="header-anchor" href="#开发挑战" aria-label="Permalink to &quot;开发挑战&quot;">​</a></h3><ul><li>Tauri:社区生态相对较新是当前的一个挑战，与更成熟的选项相比，Tauri 可能拥有较小的社区和较少的第三方库。</li><li>Electron:提升性能、内存和包大小优化是常见挑战。</li><li>React Native:管理原生依赖,实现跨平台高性能是较大挑战。</li><li>Flutter:实现高度自定义和不同操作系统之间一致性需要额外工作。</li><li>Qt:相对陡峭的学习曲线,深度整合系统功能复杂度较高。</li></ul><h3 id="总体比较" tabindex="-1">总体比较 <a class="header-anchor" href="#总体比较" aria-label="Permalink to &quot;总体比较&quot;">​</a></h3><p>比较总结，1打10分为每项比较项打分，分越高代表此项越好，这些分数是基于上面的对比和分析打出的主观评分,可以作为参考,但不是绝对评判。不同项目和团队对于框架的需求可能有所不同,需要结合具体情况权衡利弊。</p><table tabindex="0"><thead><tr><th>框架</th><th>性能</th><th>用户界面</th><th>原生集成</th><th>社区生态</th><th>成功案例</th><th>开发经验</th><th>开发挑战</th></tr></thead><tbody><tr><td>Tauri</td><td>9</td><td>8</td><td>9</td><td>7</td><td>7</td><td>8</td><td>7</td></tr><tr><td>Electron</td><td>5</td><td>8</td><td>6</td><td>9</td><td>9</td><td>9</td><td>8</td></tr><tr><td>React Native</td><td>6</td><td>7</td><td>7</td><td>9</td><td>9</td><td>8</td><td>7</td></tr><tr><td>Flutter</td><td>8</td><td>8</td><td>7</td><td>8</td><td>7</td><td>7</td><td>7</td></tr><tr><td>Qt</td><td>9</td><td>9</td><td>10</td><td>6</td><td>8</td><td>6</td><td>5</td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Tauri是一个全新的桌面端框架,它采用了一种独特的三层架构,将Web前端与Rust后端相结合。相比传统的桌面应用程序框架,Tauri具有更小的二进制文件大小(仅7.5MB)、更高的性能(CPU使用率仅为14.5%)、更好的安全性(严格的沙箱机制)和更好的与操作系统API的集成能力。 凭借其卓越的性能表现和可靠的安全性,Tauri为开发者提供了一种全新的构建桌面应用程序的方式。它已经被广泛应用于各种类型的应用场景,如本地化工具、多媒体应用、游戏和娱乐应用、办公和生产力工具等。 随着Tauri社区的不断发展和完善,我们可以期待它在未来会有更加广泛的应用和发展前景,为开发者提供更加高效、安全和可靠的桌面应用程序解决方案。</p>',33)]))}const m=a(d,[["render",u]]);export{p as __pageData,m as default};
